use notepad_core::{find_all,FindMatch,FindOptions};#[derive(Debug,Clone)]pub struct FindBarState{pub open:bool,pub query:String,pub options:FindOptions,pub matches:Vec<FindMatch>,pub current:usize}impl Default for FindBarState{fn default()->Self{Self{open:false,query:String::new(),options:FindOptions::default(),matches:Vec::new(),current:0}}}impl FindBarState{pub fn refresh(&mut self,text:&str)->Result<(),String>{self.matches=find_all(text,&self.query,&self.options).map_err(|e|e.to_string())?;self.current=self.current.min(self.matches.len().saturating_sub(1));Ok(())}pub fn counter(&self)->String{if self.matches.is_empty(){"0 matches".into()}else{format!("{} of {}",self.current+1,self.matches.len())}}}
